typedef unsigned int size_t;

void* operator new(size_t, unsigned int, const char*, int);

class stringx
{
  int data[2];
public:
  stringx(const stringx&);
  ~stringx();
};

struct color32
{
  unsigned int value;
};

class Font
{
public:
  enum HORIZJUST { HORIZJUST_LEFT, HORIZJUST_CENTER, HORIZJUST_RIGHT };
  enum VERTJUST { VERTJUST_TOP, VERTJUST_CENTER, VERTJUST_BOTTOM };
};

class TextString
{
  Font* font;
  stringx text;
  float x;
  float y;
  int z;
  Font::HORIZJUST hJustify;
  Font::VERTJUST vJustify;
  bool even_number_spacing;
  int fade;
  float fade_alpha;
  float fade_timer;
  float scale;
  float button_scale;
  bool override_alpha;
public:
  bool checkTime;
  float time;
  bool no_color;
  color32 color;

  TextString(Font* f, stringx t, float x1, float y1, int z1, float s,
             Font::HORIZJUST horizJust, Font::VERTJUST vertJust, color32 col)
  {
    cons(f, t, x1, y1, z1, s, horizJust, vertJust, false, col);
  }
  virtual ~TextString();
protected:
  virtual void cons(Font*, stringx, float, float, int, float,
                    Font::HORIZJUST, Font::VERTJUST, bool, color32);
};

class IGOWidget
{
protected:
  bool display;
public:
  IGOWidget();
  virtual ~IGOWidget();
  virtual void SetDisplay(bool);
  virtual void Update(float);
  virtual void Draw();
  virtual bool GetDisplay() const;
};

class PanelQuad;
class PanelFile;

class ReplayWidget : public IGOWidget
{
public:
  enum VCRButtonState { VCR_RESTART, VCR_PAUSE, VCR_PLAY, VCR_SLOW, VCR_FASTFORWARD };
private:
  int vcrButton;
  int vcrButtonHL;
  PanelQuad* vcrPQ;
  PanelQuad* vcrHLPQ;
  PanelQuad* vcrBGPQ;
  PanelQuad* restartPQ;
  PanelQuad* restartOffPQ;
  PanelQuad* restartHLPQ;
  PanelQuad* pausePQ;
  PanelQuad* pauseOffPQ;
  PanelQuad* pauseHLPQ;
  PanelQuad* playPQ;
  PanelQuad* playOffPQ;
  PanelQuad* playHLPQ;
  PanelQuad* slowPQ;
  PanelQuad* slowOffPQ;
  PanelQuad* slowHLPQ;
  PanelQuad* fastforwardPQ;
  PanelQuad* fastforwardOffPQ;
  PanelQuad* fastforwardHLPQ;
  TextString* pauseText;
  float highlight_intensity;
  float highlight_timer;
public:
  ReplayWidget();
  virtual ~ReplayWidget();
  virtual void SetDisplay(bool);
  virtual void Init(PanelFile&, Font*);
  virtual void Update(float);
  virtual void Draw();
  virtual void Select(int);
  virtual void SelectHighlight(int);
  virtual void HighlightLeft();
  virtual void HighlightRight();
  virtual int GetButton();
  virtual int GetHighlight();
};

struct FrontEndManager
{
  char padding[0x25634];
  color32 col_highlight;
};

extern stringx ksGlobalTextArray[];
extern FrontEndManager frontendmanager;

#define NULL 0
#define NEW new(0, __FILE__, __LINE__)
enum { GT_REPLAY_PAUSED = 57 };

ReplayWidget::ReplayWidget()
{
  vcrButton       = VCR_PLAY;
  vcrButtonHL     = VCR_PLAY;

  vcrPQ             = NULL;
  vcrHLPQ           = NULL;
  vcrBGPQ           = NULL;
  restartPQ         = NULL;
  restartOffPQ      = NULL;
  restartHLPQ       = NULL;
  pausePQ           = NULL;
  pauseOffPQ        = NULL;
  pauseHLPQ         = NULL;
  playPQ            = NULL;
  playOffPQ         = NULL;
  playHLPQ          = NULL;
  slowPQ            = NULL;
  slowOffPQ         = NULL;
  slowHLPQ          = NULL;
  fastforwardPQ     = NULL;
  fastforwardOffPQ  = NULL;
  fastforwardHLPQ   = NULL;

  int tx = 320, ty = 400;
  //unadjustSizes(tx, ty);
  pauseText = NEW TextString(NULL, ksGlobalTextArray[GT_REPLAY_PAUSED], tx, ty, 800, 1.0f, Font::HORIZJUST_CENTER, Font::VERTJUST_CENTER, frontendmanager.col_highlight);
}
